"use strict";(self.webpackChunkwiki_es=self.webpackChunkwiki_es||[]).push([["62160"],{5022(e){e.exports=JSON.parse('{"tag":{"label":"reComputer","permalink":"/es/tags/re-computer","allTagsPath":"/es/tags","count":6,"items":[{"id":"Edge/NVIDIA_Jetson/Application/Computer_Vision/es_Streaming_Vision_Agent_on_Jetson","title":"Agente de Visi\xf3n en Streaming en Jetson","description":"Implementa un Agente de Visi\xf3n en Streaming en NVIDIA Jetson con memoria multimodal rodante dual Qwen3-VL-2B y una interfaz Ask en vivo","permalink":"/es/streaming_vision_agent_on_jetson"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/es_reComputer_Robotics_Hardware_Interfaces_Usage","title":"Hardware y Uso de Interfaces de reComputer Robotics","description":"Esta wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y el uso de interfaces de la placa portadora reComputer Jetson Robotics J401. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como M.2, Ethernet, USB, CAN, UART, I2C y expansi\xf3n de c\xe1mara GMSL2, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J401.","permalink":"/es/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Mini/es_reComputer_Mini_Hardware_Interfaces_Usage","title":"Hardware y Uso de Interfaces del reComputer Mini","description":"Este art\xedculo cubre el hardware y las interfaces de la serie reComputer Mini J40, incluyendo alimentaci\xf3n, pantalla, ranuras M.2 para Wi-Fi y SSD, puertos USB, RTC, gesti\xf3n del ventilador, y m\xe1s. Proporciona instrucciones de configuraci\xf3n y consejos de pruebas de rendimiento para ayudar a los usuarios a expandir sus proyectos.","permalink":"/es/recomputer_jetson_mini_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/es_reComputer_Robotics_Getting_Started","title":"Introducci\xf3n a reComputer Robotics","description":"La reComputer Robotics J401 es una placa portadora de IA de borde de alto rendimiento dise\xf1ada para aplicaciones avanzadas de rob\xf3tica. Es compatible con los m\xf3dulos NVIDIA Jetson Orin Nano y Orin NX en modo Super/MAXN, ofreciendo hasta 157 TOPS de potencia de c\xf3mputo de IA. La placa ofrece amplias opciones de conectividad, incluyendo Ethernet Gigabit dual, m\xfaltiples puertos USB 3.2, CAN, ranuras M.2 para m\xf3dulos 5G/Wi\u2011Fi/BT y compatibilidad opcional con c\xe1maras GMSL2. Con JetPack 6 preinstalado, garantiza un despliegue fluido para el desarrollo de rob\xf3tica. El dise\xf1o robusto admite un amplio rango de temperaturas de funcionamiento e incluye un disipador de calor con ventilador preinstalado. La configuraci\xf3n implica flashear el sistema operativo JetPack en un SSD NVMe usando un PC host Ubuntu compatible, seguido de la configuraci\xf3n del hardware y el uso de las interfaces. Se proporcionan especificaciones detalladas de hardware, dibujos mec\xe1nicos y recursos t\xe9cnicos para desarrolladores, junto con canales de soporte t\xe9cnico y de comunidad para resoluci\xf3n de problemas y discusi\xf3n.","permalink":"/es/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Application/Computer_Vision/es_industrial_vision_monitoring_on_industrial","title":"Monitorizaci\xf3n de Visi\xf3n Industrial en Industrial","description":"Implementa una demo de monitorizaci\xf3n de visi\xf3n industrial en NVIDIA Jetson con detecci\xf3n de objetos YOLO y an\xe1lisis de comportamiento con VLM","permalink":"/es/industrial_vision_monitoring_on_industrial"},{"id":"Edge/NVIDIA_Jetson/JetPack_7_2/AI_Inference/es_industrial_vision_monitoring_on_industrial_bk","title":"Monitorizaci\xf3n de Visi\xf3n Industrial en Industrial","description":"Implementa una demostraci\xf3n de monitorizaci\xf3n de visi\xf3n industrial en NVIDIA Jetson con detecci\xf3n de objetos YOLO y an\xe1lisis de comportamiento mediante VLM","permalink":"/es/industrial_vision_monitoring_on_industrial_bk"}],"unlisted":false}}')}}]);